# Sizing calculations, BOM accounting and final integration.
c=concept(630,'Motor and transmission sizing audit','Ideal reduction, angular-unit conversion, omitted loads and linear/rotary dimensional consistency.')
GF=fm('τm=τout/(ηN); τout=Iout αout for the isolated rotary inertial load; ωm=Nωout',{'τm':'required motor torque magnitude','τout':'required output torque magnitude','η':'forward transmission efficiency','N':'motor-speed/output-speed reduction ratio','Iout':'load inertia referred to output shaft','αout':'output angular acceleration','ωm,ωout':'motor/output angular speed magnitudes'},{'τm,τout':'N m','η,N':'dimensionless','Iout':'kg m²','αout':'rad/s²','ωm,ωout':'rad/s'},['Forward driving; η=1 for the source’s ideal relation. Rotor inertia, friction, gravity and coupling are included only if explicitly supplied.'])
ask(c,'What is300°/s² in rad/s²?', ['5π/3≈5.236 rad/s²','52.4 rad/s²','300π≈942.478 rad/s²','300/π≈95.493 rad/s²'],['Multiply300 byπ/180.','This is about3000°/s², not300°/s².','This omits division by180.','Degrees-to-radians conversion multiplies byπ/180, not1/π.'],kind='numerical',steps=['Use1°=π/180 rad.','300×π/180=5π/3≈5.235988 rad/s².'],conflict=(630,'The J1 row equates52.4 rad/s² with300°/s².','The exact conversion is300π/180=5π/3 rad/s². The printed52.4 is approximately ten times that value.'))
ask(c,'Use the literal52.4 rad/s² acceleration, output inertia0.042 kg m² and an ideal100:1 reducer. Considering only this load’s acceleration, what motor torque follows?', ['0.022008 N m','2.2008 N m','2.4 N m','220.08 N m'],['OutputIα=2.2008 N m, then divide by100.','This is the output torque before reduction.','This is the listed motor value, not the result of the stated isolated-load calculation.','This multiplies output torque by the reducer ratio rather than dividing.'],kind='numerical',difficulty='medium',formula=[GF],steps=['Computeτout=0.042×52.4=2.2008 N m.','Setη=1 andN=100.','Computeτm=2.2008/100=0.022008 N m.'],assumptions=['Literal52.4 rad/s² scenario; not the contradictory300°/s² annotation. Ignore all unprovided additional loads and motor inertia.'])
ask(c,'For output inertia0.018 kg m², acceleration52.4 rad/s² and an ideal80:1 reducer, what is the analogous load-only motor torque?', ['0.01179 N m','0.9432 N m','1.1 N m','75.456 N m'],['0.018×52.4/80=0.01179.','This is output torque before dividing by80.','This is the chosen table value, not the isolated-load calculation.','This multiplies by80 instead of dividing.'],kind='numerical',formula=[GF],steps=['τout=0.018×52.4=0.9432 N m.','τm=0.9432/80=0.01179 N m.'],assumptions=['Ideal load-only computation; ignore all unprovided rotor inertia, friction, coupling and margins.'])
ask(c,'Do the load-only torque results prove the selected750 W and400 W motors are incorrectly sized?', ['No; a complete sizing decision also needs speed, duty/RMS torque, rotor inertia, losses, coupling and margins','Yes; nominal motor power always equals Iα numerically','Yes; a motor rating must exactly equal the smallest computed instantaneous load torque','No; gearbox ratio alone proves every possible motor is suitable'],['The table lacks the full data needed to validate or reject the chosen ratings.','Power and torque have different units and require speed for conversion.','A selected rating can exceed a simplified load estimate for legitimate reasons.','Motor capability is not determined solely by ratio.'],difficulty='medium',formula=[GF])
ask(c,'Why can the Z-axis row’s0.005 kg m² not simply be multiplied by40 m/s² to obtain a force?', ['Rotary inertia times linear acceleration has units kg m³/s², not newtons; a consistent mass/shaft model is needed','The multiplication is forbidden only because0.005 is a decimal','The result is automatically18 N for any screw lead','The ball screw removes the need to distinguish force and torque'],['A newton is kg m/s²; the given rotary-inertia units introduce an extra length squared.','Decimal values can be multiplied normally.','Neither dimensional analysis nor the supplied numbers gives18 N directly.','A screw relates torque and force but does not erase their units.'],difficulty='medium',conflict=(630,'The Z-axis load appears under a kg m² inertia header while the acceleration is40 m/s² and the peak entry is18 N.','A rotary inertia needs a specified kinematic transformation to linear effective mass, or a moving mass must be supplied. The row alone does not establish the stated linear force.'))
ask(c,'Ignoring friction, what upward force accelerates the table’s1.3 kg payload upward at40 m/s² with g=9.81 m/s²?', ['64.753 N','18 N','52 N','12.753 N'],['F=m(a+g)=1.3×49.81=64.753 N.','18 N is the listed value but cannot produce the stated upward acceleration for this mass.','52 N omits gravity.','12.753 N is the static weight only.'],kind='numerical',difficulty='medium',pages=[628,630],steps=['Take upward as positive for this explicit scenario.','Newton’s law:F−mg=ma.','F=1.3(40+9.81)=64.753 N.'],formula=[fm('F=m(a+g)',{'F':'upward actuator force','m':'total accelerating mass in this scenario','a':'upward acceleration','g':'positive gravitational acceleration'},{'F':'N','m':'kg','a,g':'m/s²'},['Vertical motion; no friction, counterbalance or other support. Only the stated1.3 kg load is included.'])])
ask(c,'The direct-drive wrist has I=0.0008 kg m² and α=200 rad/s². What inertial torque and ratio to the listed0.32 N m value follow?', ['0.16 N m, so0.32 N m is twice the load-only value','0.32 N m, so the ratio is1','0.000004 N m, so the ratio is80000','160 N m, so0.32 N m is larger'],['Iα=0.0008×200=0.16;0.32/0.16=2.','This inserts an unstated factor2 intoIα.','This divides inertia by acceleration instead of multiplying.','This loses a factor1000 and reverses the comparison.'],kind='numerical',steps=['MultiplyIα=0.16 N m.','Divide the stated motor value0.32 by0.16 to obtain2.','The reason for this apparent margin is not specified by the slide.'],assumptions=['Isolated direct-drive inertial load; ignore all other torque terms.'])
ask(c,'For an80:1 reducer with efficiency0.8 and a required output torque8 N m, what motor torque is required in forward driving?', ['0.125 N m','0.100 N m','0.080 N m','512 N m'],['8/(0.8×80)=0.125.','This ignores the efficiency loss.','This multiplies by efficiency rather than compensating for it.','This multiplies output torque by both ratio and efficiency.'],kind='numerical',formula=[GF],steps=['ComputeηN=0.8×80=64.','Divide8 N m by64 to get0.125 N m.'])
