# Add spaces at word-number boundaries in explanatory prose without rewriting variables or source quotations.
import re
words='for|lead|efficiency|revised|lasting|required|literal|printed|payload|Payload|reach|cycle|repeatability|inertia|torque|stroke|target|radius|quantity|converts|folded|reaching|degrees|times|exceeds|exceed|gains|of|the|a|an|one|two|three|four|both|only|and|or|at|by|from|to|is|of|with|Set|Compute|Divide|Multiply|Add|Subtract|Use|Total|About|about|than|below|above|equals|obtain|gives|giving|cost|costs|giving|Choose|Sum|since|Since'
def readable(v):
 if isinstance(v,str):
  v=re.sub(r'\b(and|or|to|from|is|are|gives|for|with|at|leaving|Set|Compute|Use|Only|only|then)(?=[A-Za-z][0-9])',r'\1 ',v)
  v=re.sub(r'\b([A-Za-z]{3,})(?=[0-9])',lambda m:m.group(1) if m.group(1)=='atan' else m.group(1)+' ',v)
  v=re.sub(r'\b([A-Za-z]{2,})(?=[θφωταΔ])',r'\1 ',v)
  v=re.sub(r'\b(as|in|of)(?=[0-9])',r'\1 ',v)
  v=re.sub(r',(?=\S)',', ',v)
  v=re.sub(r';(?=\S)','; ',v)
  v=re.sub(r'(?<=[’])(?=[0-9])',' ',v)
  v=re.sub(r'(?<=[A-Za-z])(?=±)',' ',v)
  v=re.sub(r'\b('+words+r')(?=[0-9])',r'\1 ',v)
  v=v.replace('givesta','gives ta').replace('givesr','gives r').replace('thenα','then α').replace('andk2','and k2').replace('soT','so T').replace('andrates','and rates').replace('the next page’s0.5','the next page’s 0.5').replace('anR-30iB','an R-30iB').replace('Setm34','Set m34').replace('ComputeI2','Compute I2').replace('Usezdot','Use zdot').replace('Useφ','Use φ').replace('Solveθ4','Solve θ4').replace('Choose negativeθ2','Choose negative θ2').replace('one120-dollar','one 120-dollar')
  return v
 if isinstance(v,list):return[readable(x) for x in v]
 if isinstance(v,dict):return{k:readable(x) for k,x in v.items()}
 return v
for q in Q:
 for k in ('stem','options','assumptions','solution'):q[k]=readable(q[k])
